import json
import re


def extract_id(link):
    if not isinstance(link, dict):
        return ""
    url = ((link.get("links") or {}).get("self")) or ""
    m = re.search(r"/(\d+)(?:$|\?)", str(url))
    return m.group(1) if m else ""


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


# Every configured practice, not a single hardcoded one — PracticeManager/Practices/*.json
# is the real list (see Apply practice setup), so this scales past the pilot practice
# without anyone editing this automation.
practices = []
try:
    entries = api.files.list(path="PracticeManager/Practices", scope="org")
except Exception:
    entries = []
for entry in entries or []:
    fname = entry.get("name") if isinstance(entry, dict) else entry
    if not fname or not str(fname).endswith(".json"):
        continue
    slug = str(fname)[:-5]
    practice = read_json("PracticeManager/Practices/" + fname, {}) or {}
    if practice:
        practices.append({"slug": slug, "practice": practice})

result = api.connectors.invoke(
    server="cliniko-scheduling",
    tool="list_individual_appointments",
    args={"q": ["did_not_arrive:=true"], "sort": "starts_at:desc", "per_page": 50},
)
rows = (result or {}).get("individual_appointments") or []

new_items = []
for p in practices:
    business_id = str(p["practice"].get("cliniko_business_id") or "")
    seen = read_json("PracticeManager/NoShows/" + p["slug"] + ".json", []) or []
    seen_ids = {str(x) for x in seen}
    for row in rows:
        appt_id = str(row.get("id") or "")
        row_business_id = extract_id(row.get("business"))
        if not appt_id or appt_id in seen_ids:
            continue
        if business_id and row_business_id and row_business_id != business_id:
            continue
        new_items.append({
            "slug": p["slug"],
            "practice": p["practice"],
            "appointment_id": appt_id,
            "patient_name": row.get("patient_name") or "",
            "patient_id": extract_id(row.get("patient")),
            "practitioner_id": extract_id(row.get("practitioner")),
            "business_id": row_business_id,
            "appointment_type_id": extract_id(row.get("appointment_type")),
            "starts_at": row.get("starts_at") or "",
        })

import json
import re
import datetime

AI_PROMPT = (
    "You are drafting a short, warm follow-up email on behalf of a healthcare clinic to a patient who did not "
    "arrive for their appointment. Offer to rebook using the times given, mention the clinic's cancellation "
    "policy in one brief sentence, and match the tone instructed. Never give clinical advice, diagnosis or "
    "interpretation. Keep it under 120 words."
)
AI_HINT = '{"subject": "", "body": ""}'


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True))


def format_time(iso):
    # No tool here exposes the practice's configured timezone, so times are shown
    # plainly rather than guessing one — same constraint as the No Shows tile.
    return str(iso or "").replace("T", " ").replace("Z", " UTC")


def practice_today(settings):
    tz_name = (settings or {}).get("timezone") or "UTC"
    try:
        from zoneinfo import ZoneInfo
        return datetime.datetime.now(ZoneInfo(tz_name)).date()
    except Exception:
        return datetime.datetime.now(datetime.timezone.utc).date()


item = params.get("item") or {}
slug = item.get("slug") or ""
practice = item.get("practice") or {}
appointment_id = item.get("appointment_id") or ""
patient_id = item.get("patient_id") or ""
patient_name = item.get("patient_name") or "this patient"
outcome = "skipped"
workq_id = ""

if slug and appointment_id:
    policy = practice.get("policy") or {}
    tone = policy.get("tone") or "warm, concise, no jargon"
    window_hours = policy.get("cancellation_window_hours") or 24

    slots = []
    if item.get("practitioner_id") and item.get("business_id") and item.get("appointment_type_id"):
        try:
            today = practice_today(practice)
            avail = api.connectors.invoke(
                server="cliniko-scheduling",
                tool="get_available_times",
                args={
                    "business_id": item["business_id"],
                    "practitioner_id": item["practitioner_id"],
                    "appointment_type_id": item["appointment_type_id"],
                    "from_time": today.isoformat(),
                    "to_time": (today + datetime.timedelta(days=6)).isoformat(),
                },
            )
            raw_slots = avail if isinstance(avail, list) else (avail or {}).get("available_times") or []
            for s in raw_slots[:3]:
                t = s.get("appointment_start") if isinstance(s, dict) else s
                if t:
                    slots.append(format_time(t))
        except Exception:
            slots = []

    email = ""
    if patient_id:
        try:
            patient = api.connectors.invoke(server="cliniko-patients", tool="get_patient", args={"id": patient_id})
            email = (patient or {}).get("email") or ""
        except Exception:
            email = ""

    try:
        drafted = api.ai.extract(
            prompt=AI_PROMPT,
            input=json.dumps({
                "patient_name": patient_name,
                "missed_time": format_time(item.get("starts_at")),
                "available_times": slots,
                "cancellation_window_hours": window_hours,
                "tone": tone,
            }),
            schema_hint=AI_HINT,
        )
    except Exception:
        drafted = {}
    drafted = drafted if isinstance(drafted, dict) else {}
    subject = drafted.get("subject") or "We missed you"
    body = drafted.get("body") or (
        "Hi " + patient_name + ", we noticed you weren't able to make your recent appointment. "
        "Reply to this email or call us to rebook."
    )

    description = (
        "**Patient:** " + patient_name + "  \n"
        "**Missed appointment:** " + format_time(item.get("starts_at")) + "  \n"
        "**Email on file:** " + (email or "none on file") + "  \n\n"
        "**Drafted subject:** " + subject + "  \n\n"
        "**Drafted message:**\n\n" + body
    )
    if not email:
        description += "\n\n_No email on file for this patient — \"Send as drafted\" won't be able to send._"

    reviewer = practice.get("reviewer_id") or ""
    workq_item = api.workq.create(
        title="No-show follow-up: " + patient_name,
        scope="org",
        description=description,
        priority="normal",
        assignee_ids=[reviewer] if reviewer else None,
        labels=["healthcare-practice-management", "no-show-recovery"],
    )
    workq_id = workq_item["id"]
    api.workq.attach_form(todo_id=workq_id, form_id=params["approval_form"])

    write_json("PracticeManager/NoShowDrafts/" + workq_id + ".json", {
        "slug": slug,
        "appointment_id": appointment_id,
        "patient_id": patient_id,
        "patient_name": patient_name,
        "email": email,
        "subject": subject,
        "body": body,
    })

    seen = read_json("PracticeManager/NoShows/" + slug + ".json", []) or []
    seen_set = {str(x) for x in seen}
    seen_set.add(appointment_id)
    write_json("PracticeManager/NoShows/" + slug + ".json", sorted(seen_set))

    outcome = "requested_approval"
